# -*- coding: utf-8 -*-
"""Offline browser client for the MyAutoTrain collaborative annotation server."""

ANNOTATION_HTML = r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>MyAutoTrain 协作标注中心</title>
<style>
:root{--bg:#fff7f7;--panel:#fff;--line:#eddada;--text:#302525;--muted:#806d6d;--red:#dc3838;--red2:#ef706c;--green:#1f9960;--orange:#d17a24;--shadow:0 14px 38px rgba(110,35,35,.11)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 90% 0,#ffe1e1,transparent 32%),var(--bg);color:var(--text);font:14px/1.45 "Microsoft YaHei UI",system-ui,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.hidden{display:none!important}.top{height:68px;padding:0 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:rgba(255,255,255,.94);position:sticky;top:0;z-index:20}.brand{display:flex;align-items:center;gap:11px}.logo{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--red),var(--red2));color:#fff;display:grid;place-items:center;font-weight:800}.brand b{display:block;font-size:17px}.brand span,.muted{color:var(--muted);font-size:12px}.top-actions{display:flex;align-items:center;gap:9px}.pill{padding:7px 10px;border-radius:999px;background:#fff3f3;border:1px solid #f0caca;color:#a72d2d}.btn{border:1px solid #e5cece;background:#fff;color:#5a4343;border-radius:11px;padding:9px 12px}.btn:hover{background:#fff2f2}.btn.primary{border:0;color:#fff;background:linear-gradient(135deg,var(--red),var(--red2))}.btn.green{border:0;color:#fff;background:var(--green)}.btn.warn{color:#a85f18;border-color:#ebc99f;background:#fff8ed}.btn.danger{color:#bd2f2f;border-color:#efb7b7}.shell{display:grid;grid-template-columns:250px minmax(420px,1fr) 300px;gap:14px;padding:14px;height:calc(100vh - 68px)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow);min-height:0;overflow:hidden}.left,.right{display:flex;flex-direction:column}.panel-head{padding:15px;border-bottom:1px solid var(--line)}.panel-head h2,.panel-head h3{margin:0 0 5px}.scroll{overflow:auto;padding:10px;min-height:0}.project{width:100%;text-align:left;padding:11px;border:1px solid transparent;border-radius:12px;background:transparent;color:var(--text);margin-bottom:5px}.project:hover,.project.active{background:#fff1f1;border-color:#efcaca}.project b,.project span{display:block}.project span{font-size:11px;color:var(--muted);margin-top:3px}.center{display:flex;flex-direction:column}.toolbar{padding:11px 13px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:8px;flex-wrap:wrap}.toolbar .grow{flex:1}.workspace{flex:1;min-height:0;overflow:auto;display:grid;place-items:center;padding:16px;background:linear-gradient(45deg,#f6eeee 25%,transparent 25%),linear-gradient(-45deg,#f6eeee 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#f6eeee 75%),linear-gradient(-45deg,transparent 75%,#f6eeee 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}.canvas-wrap{position:relative;line-height:0;box-shadow:0 8px 30px rgba(50,20,20,.18);background:#1e1b1b}.canvas-wrap canvas{display:block;max-width:min(100%,1200px);max-height:calc(100vh - 205px);width:auto;height:auto;touch-action:none}.empty{padding:32px;text-align:center;color:var(--muted);border:1px dashed #dfc7c7;border-radius:14px}.status-row{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;padding:12px;border-bottom:1px solid var(--line)}.stat{padding:8px;border-radius:11px;background:#fff7f7;text-align:center}.stat b{display:block;font-size:18px}.stat span{font-size:10px;color:var(--muted)}.item{padding:10px;border:1px solid #eddede;border-radius:11px;margin-bottom:6px;background:#fff;text-align:left;width:100%}.item:hover,.item.active{border-color:#e88e8e;background:#fff4f4}.item b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.item span{font-size:11px;color:var(--muted)}.badge{display:inline-flex;padding:3px 6px;border-radius:999px;background:#f4eded;font-size:10px;margin-right:4px}.badge.approved{color:#16784b;background:#eaf8f0}.badge.submitted{color:#9d601b;background:#fff4e4}.badge.rejected{color:#bd2f2f;background:#fff0f0}.labels{display:flex;gap:6px;flex-wrap:wrap}.label-btn{border:2px solid transparent;border-radius:10px;padding:8px 10px;background:#f5eded}.label-btn.active{border-color:#4b3d3d;background:#fff}.box-row{display:flex;align-items:center;gap:7px;padding:8px;border-bottom:1px solid #f1e5e5}.swatch{width:10px;height:10px;border-radius:3px}.box-row b{flex:1;font-size:12px}.forms{display:grid;gap:8px}.field{display:grid;gap:4px}.field label{font-size:11px;color:var(--muted)}input,select,textarea{width:100%;border:1px solid #e2cccc;border-radius:10px;padding:9px;background:#fff;color:var(--text)}textarea{min-height:70px;resize:vertical}.section-card{padding:12px;border-top:1px solid var(--line)}.section-card h4{margin:0 0 9px}.review-note{padding:9px;border-radius:10px;background:#fff5e9;color:#925819;font-size:12px;margin:8px 0}.modal-backdrop{position:fixed;inset:0;z-index:100;background:rgba(44,25,25,.42);display:grid;place-items:center;padding:18px}.modal{width:min(430px,100%);background:#fff;border-radius:20px;padding:24px;box-shadow:0 26px 80px rgba(55,20,20,.3)}.modal h1{margin:0 0 6px}.modal p{color:var(--muted)}.modal .forms{margin-top:18px}.toast{position:fixed;right:18px;bottom:18px;z-index:200;padding:11px 15px;border-radius:11px;color:#fff;background:#9f2d2d;opacity:0;transform:translateY(8px);transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:none}.drawer{position:fixed;inset:76px 18px 18px auto;width:min(440px,calc(100% - 36px));z-index:60;background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 24px 70px rgba(60,25,25,.25);overflow:auto;padding:18px}.drawer h2{margin-top:0}.drawer-close{float:right}.help{padding:11px;background:#fff7f7;border-radius:11px;color:var(--muted);font-size:12px;margin:9px 0}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}@media(max-width:1050px){.shell{grid-template-columns:220px 1fr}.right{position:fixed;right:12px;top:80px;bottom:12px;width:300px;z-index:40}.right.mobile-hidden{display:none}.shell{padding-right:14px}}@media(max-width:720px){.shell{grid-template-columns:1fr;height:auto}.left{max-height:300px}.center{min-height:620px}.top{padding:0 12px}.brand span{display:none}.right{left:12px;width:auto}.canvas-wrap canvas{max-height:70vh}.top-actions .pill{display:none}}
</style>
</head>
<body>
<header class="top"><div class="brand"><div class="logo">MA</div><div><b>MyAutoTrain 协作标注中心</b><span id="modeText">本地优先 · 正在连接</span></div></div><div class="top-actions"><span class="pill" id="userPill">未登录</span><button class="btn" onclick="toggleAdmin()">项目管理</button><button class="btn" onclick="toggleRight()">标注面板</button><button class="btn" onclick="logout()">退出</button></div></header>
<div id="app" class="shell hidden">
  <aside class="panel left"><div class="panel-head"><h2>项目</h2><span class="muted" id="projectHint">选择一个项目开始工作</span></div><div id="projects" class="scroll"><div class="empty">暂无项目</div></div></aside>
  <main class="panel center">
    <div class="toolbar"><select id="statusFilter" onchange="loadItems()"><option value="">全部状态</option><option value="assigned">待标注</option><option value="in_progress">标注中</option><option value="submitted">待审核</option><option value="approved">已通过</option><option value="rejected">已驳回</option><option value="unassigned">未分配</option></select><button class="btn" onclick="loadItems()">刷新任务</button><span class="grow muted" id="itemTitle">尚未打开图片</span><button class="btn" onclick="previousItem()">上一张</button><button class="btn" onclick="nextItem()">下一张</button></div>
    <div id="workspace" class="workspace"><div class="empty">选择左侧项目，再从右侧任务队列打开图片。</div></div>
  </main>
  <aside id="rightPanel" class="panel right mobile-hidden">
    <div class="status-row"><div class="stat"><b id="countAll">0</b><span>全部</span></div><div class="stat"><b id="countMine">0</b><span>当前列表</span></div><div class="stat"><b id="countApproved">0</b><span>已通过</span></div></div>
    <div class="section-card"><h4>当前类别</h4><div id="labels" class="labels"><span class="muted">先选择项目</span></div></div>
    <div id="boxes" class="scroll" style="flex:1"><div class="empty">绘制框后显示在这里</div></div>
    <div class="section-card"><div id="reviewComment" class="review-note hidden"></div><div class="actions"><button class="btn" onclick="saveItem(false)">保存进度</button><button class="btn primary" onclick="saveItem(true)">提交审核</button><button id="approveBtn" class="btn green hidden" onclick="reviewItem(true)">审核通过</button><button id="rejectBtn" class="btn warn hidden" onclick="reviewItem(false)">驳回修改</button></div></div>
    <div class="panel-head"><h3>任务队列</h3></div><div id="items" class="scroll" style="max-height:35%"><div class="empty">暂无任务</div></div>
  </aside>
</div>
<div id="adminDrawer" class="drawer hidden"><button class="btn drawer-close" onclick="toggleAdmin(false)">关闭</button><h2>项目与团队</h2><div id="shareInfo" class="help"></div><div id="managerArea">
  <div class="section-card"><h4>创建项目并导入服务端图片</h4><div class="forms"><div class="field"><label>项目名称</label><input id="newProjectName" placeholder="例如 PCB 缺陷检测"></div><div class="field"><label>类别（逗号分隔）</label><input id="newProjectLabels" placeholder="normal, scratch, dent"></div><div class="field"><label>服务端图片文件夹</label><input id="newProjectSource" placeholder="例如 D:/datasets/pcb/images"></div></div><div class="actions"><button class="btn primary" onclick="createProject()">创建并导入</button></div></div>
  <div class="section-card"><h4>创建成员</h4><div class="forms"><input id="newUsername" placeholder="用户名"><input id="newPassword" type="password" placeholder="至少 8 位密码"><select id="newRole"><option value="annotator">标注员</option><option value="reviewer">审核员</option><option value="admin">管理员</option></select></div><div class="actions"><button class="btn" onclick="createUser()">创建账号</button></div></div>
  <div class="section-card"><h4>分配未标注图片</h4><div class="forms"><select id="assignUser"></select><input id="assignCount" type="number" min="1" value="50"></div><div class="actions"><button class="btn" onclick="assignTasks()">分配任务</button></div></div>
  <div class="section-card"><h4>项目包交换</h4><div class="help">个人项目可导出为 .matproj.zip，再在另一台电脑导入。导入的已有标注会进入待审核，不会覆盖现有项目。</div><div class="forms"><input id="packagePath" placeholder="服务端上的 .matproj.zip 路径"></div><div class="actions"><button class="btn" onclick="importPackage()">导入项目包</button><button class="btn" onclick="downloadExport('project')">下载当前项目包</button></div></div>
  <div class="section-card"><h4>导出审核通过的数据集</h4><div class="actions"><button class="btn" onclick="downloadExport('yolo')">Ultralytics YOLO</button><button class="btn" onclick="downloadExport('coco')">COCO JSON</button><button class="btn" onclick="downloadExport('voc')">Pascal VOC</button><button class="btn" onclick="downloadExport('labelme')">LabelMe</button></div></div>
</div></div>
<div id="auth" class="modal-backdrop"><div class="modal"><h1 id="authTitle">协作标注中心</h1><p id="authHint">正在检查工作区...</p><div class="forms"><div class="field"><label>用户名</label><input id="authUser" autocomplete="username"></div><div class="field"><label>密码</label><input id="authPassword" type="password" autocomplete="current-password"></div><button id="authButton" class="btn primary" onclick="authenticate()">登录</button></div></div></div>
<div id="toast" class="toast"></div>
<script>
let boot={},me=null,projects=[],users=[],items=[],project=null,item=null,boxes=[],activeLabel='',image=new Image(),dragStart=null,dragCurrent=null;
const colors=['#e53935','#2a9d62','#e28a24','#3979d9','#8b5bd6','#d64e91','#167d89','#785548'];
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
async function api(path,options={}){const init={credentials:'same-origin',...options};if(init.body&&typeof init.body!=='string'){init.headers={...(init.headers||{}),'Content-Type':'application/json'};init.body=JSON.stringify(init.body)}const response=await fetch(path,init);let payload={};const type=response.headers.get('content-type')||'';if(type.includes('json'))payload=await response.json();if(!response.ok)throw new Error(payload.error||`HTTP ${response.status}`);return payload}
function statusText(value){return({unassigned:'未分配',assigned:'待标注',in_progress:'标注中',submitted:'待审核',approved:'已通过',rejected:'已驳回'})[value]||value}
function roleText(value){return({admin:'管理员',reviewer:'审核员',annotator:'标注员'})[value]||value}
async function bootstrap(){boot=await api('/api/bootstrap');document.getElementById('modeText').textContent=(boot.shared?'团队共享模式':'个人模式')+' · '+(boot.urls||[]).join(' / ');document.getElementById('shareInfo').textContent=boot.shared?`伙伴在同一局域网访问：${(boot.urls||[]).join(' 或 ')}`:'当前仅本机访问。需要协作时，请用“开启局域网共享”脚本启动。';me=boot.user||null;if(me){showApp()}else{document.getElementById('authTitle').textContent=boot.needs_setup?'创建首位管理员':'登录标注工作区';document.getElementById('authHint').textContent=boot.needs_setup?'这个账号将管理本机工作区。密码至少 8 位。':'使用管理员分配给你的账号登录。';document.getElementById('authButton').textContent=boot.needs_setup?'初始化工作区':'登录'}}
async function authenticate(){try{const body={username:document.getElementById('authUser').value,password:document.getElementById('authPassword').value};const path=boot.needs_setup?'/api/setup':'/api/login';const result=await api(path,{method:'POST',body});me=result.user;boot.needs_setup=false;showApp()}catch(error){toast(error.message)}}
async function logout(){try{await api('/api/logout',{method:'POST',body:{}})}catch(e){}location.reload()}
async function showApp(){document.getElementById('auth').classList.add('hidden');document.getElementById('app').classList.remove('hidden');document.getElementById('userPill').textContent=`${me.username} · ${roleText(me.role)}`;document.getElementById('managerArea').classList.toggle('hidden',me.role==='annotator');await Promise.all([loadProjects(),loadUsers()])}
async function loadUsers(){if(me.role==='annotator')return;try{users=(await api('/api/users')).items||[];const select=document.getElementById('assignUser');select.innerHTML='';for(const user of users.filter(x=>x.active)){const option=document.createElement('option');option.value=user.id;option.textContent=`${user.username} · ${roleText(user.role)}`;select.appendChild(option)}}catch(error){toast(error.message)}}
async function loadProjects(){projects=(await api('/api/projects')).items||[];renderProjects();if(project){const updated=projects.find(x=>x.id===project.id);if(updated){project=updated;renderCounts()}}}
function renderProjects(){const root=document.getElementById('projects');root.innerHTML='';if(!projects.length){root.innerHTML='<div class="empty">暂无可访问项目</div>';return}for(const value of projects){const button=document.createElement('button');button.className='project'+(project?.id===value.id?' active':'');const title=document.createElement('b');title.textContent=value.name;const meta=document.createElement('span');meta.textContent=`${value.item_count} 张 · ${value.approved_count} 已通过 · ${value.submitted_count} 待审核`;button.append(title,meta);button.onclick=()=>selectProject(value.id);root.appendChild(button)}}
async function selectProject(id){project=projects.find(x=>x.id===id)||null;item=null;boxes=[];renderProjects();renderLabels();renderBoxes();document.getElementById('itemTitle').textContent=project?.name||'尚未选择项目';await loadItems()}
function renderCounts(){document.getElementById('countAll').textContent=project?.item_count||0;document.getElementById('countMine').textContent=items.length;document.getElementById('countApproved').textContent=project?.approved_count||0}
async function loadItems(){if(!project)return;try{const filter=document.getElementById('statusFilter').value;items=(await api(`/api/items?project_id=${project.id}&status=${encodeURIComponent(filter)}`)).items||[];renderItems();renderCounts()}catch(error){toast(error.message)}}
function renderItems(){const root=document.getElementById('items');root.innerHTML='';if(!items.length){root.innerHTML='<div class="empty">当前筛选没有任务</div>';return}for(const value of items){const button=document.createElement('button');button.className='item'+(item?.id===value.id?' active':'');const title=document.createElement('b');title.textContent=value.relative_source;const meta=document.createElement('span');const badge=document.createElement('i');badge.className='badge '+value.status;badge.textContent=statusText(value.status);meta.append(badge,document.createTextNode(value.assignee_name?` ${value.assignee_name}`:''));button.append(title,meta);button.onclick=()=>openItem(value.id);root.appendChild(button)}}
async function openItem(id){try{item=(await api('/api/item/acquire',{method:'POST',body:{item_id:id}})).item;boxes=JSON.parse(JSON.stringify(item.boxes||[]));dragStart=null;dragCurrent=null;image=new Image();image.onload=()=>renderCanvas();image.src=item.image_url+'&t='+Date.now();document.getElementById('itemTitle').textContent=`${item.relative_source} · ${statusText(item.status)} · 版本 ${item.revision}`;renderItems();renderBoxes();renderReview();setupCanvas()}catch(error){toast(error.message)}}
function renderLabels(){const root=document.getElementById('labels');root.innerHTML='';const labels=project?.labels||[];if(!labels.length){root.innerHTML='<span class="muted">先选择项目</span>';return}if(!labels.includes(activeLabel))activeLabel=labels[0];labels.forEach((label,index)=>{const button=document.createElement('button');button.className='label-btn'+(activeLabel===label?' active':'');button.style.background=colors[index%colors.length]+'22';button.textContent=label;button.onclick=()=>{activeLabel=label;renderLabels()};root.appendChild(button)})}
function setupCanvas(){const workspace=document.getElementById('workspace');workspace.innerHTML='<div class="canvas-wrap"><canvas id="canvas"></canvas></div>';const canvas=document.getElementById('canvas');canvas.onpointerdown=event=>{if(!item?.locked_by_me)return;const point=canvasPoint(event);dragStart=point;dragCurrent=point;canvas.setPointerCapture(event.pointerId);renderCanvas()};canvas.onpointermove=event=>{if(!dragStart)return;dragCurrent=canvasPoint(event);renderCanvas()};canvas.onpointerup=event=>{if(!dragStart)return;const end=canvasPoint(event),x=Math.min(dragStart.x,end.x),y=Math.min(dragStart.y,end.y),w=Math.abs(end.x-dragStart.x),h=Math.abs(end.y-dragStart.y);if(w>=3&&h>=3)boxes.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),label:activeLabel,x,y,w,h});dragStart=null;dragCurrent=null;renderCanvas();renderBoxes()}}
function canvasPoint(event){const canvas=document.getElementById('canvas'),rect=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(item.width,(event.clientX-rect.left)*item.width/rect.width)),y:Math.max(0,Math.min(item.height,(event.clientY-rect.top)*item.height/rect.height))}}
function renderCanvas(){const canvas=document.getElementById('canvas');if(!canvas||!item||!image.complete)return;canvas.width=item.width;canvas.height=item.height;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,item.width,item.height);ctx.font=`600 ${Math.max(13,item.width/70)}px sans-serif`;ctx.lineWidth=Math.max(2,item.width/500);boxes.forEach((box,index)=>drawBox(ctx,box,index));if(dragStart&&dragCurrent){drawBox(ctx,{label:activeLabel,x:Math.min(dragStart.x,dragCurrent.x),y:Math.min(dragStart.y,dragCurrent.y),w:Math.abs(dragCurrent.x-dragStart.x),h:Math.abs(dragCurrent.y-dragStart.y)},(project.labels||[]).indexOf(activeLabel),true)}}
function drawBox(ctx,box,index,dashed=false){const labelIndex=Math.max(0,(project?.labels||[]).indexOf(box.label));const color=colors[labelIndex%colors.length];ctx.strokeStyle=color;ctx.fillStyle=color;ctx.setLineDash(dashed?[10,7]:[]);ctx.strokeRect(box.x,box.y,box.w,box.h);ctx.setLineDash([]);const text=box.label||'';const width=ctx.measureText(text).width+12,height=Math.max(20,item.width/45);ctx.fillRect(box.x,Math.max(0,box.y-height),width,height);ctx.fillStyle='#fff';ctx.fillText(text,box.x+6,Math.max(height-5,box.y-5))}
function renderBoxes(){const root=document.getElementById('boxes');root.innerHTML='';if(!boxes.length){root.innerHTML='<div class="empty">按住鼠标拖动即可绘制检测框</div>';return}boxes.forEach((box,index)=>{const row=document.createElement('div');row.className='box-row';const swatch=document.createElement('span');swatch.className='swatch';swatch.style.background=colors[Math.max(0,(project?.labels||[]).indexOf(box.label))%colors.length];const title=document.createElement('b');title.textContent=`${index+1}. ${box.label} · ${Math.round(box.w)}×${Math.round(box.h)}`;const remove=document.createElement('button');remove.className='btn danger';remove.textContent='删除';remove.onclick=()=>{boxes.splice(index,1);renderBoxes();renderCanvas()};row.append(swatch,title,remove);root.appendChild(row)})}
function renderReview(){const note=document.getElementById('reviewComment');note.classList.toggle('hidden',!item?.review_comment);note.textContent=item?.review_comment||'';const reviewer=['admin','reviewer'].includes(me.role)&&item?.status==='submitted';document.getElementById('approveBtn').classList.toggle('hidden',!reviewer);document.getElementById('rejectBtn').classList.toggle('hidden',!reviewer)}
async function saveItem(submit){if(!item)return toast('请先打开图片');try{const result=await api('/api/item/save',{method:'POST',body:{item_id:item.id,revision:item.revision,boxes,submit}});item=result.item;boxes=JSON.parse(JSON.stringify(item.boxes||[]));renderBoxes();renderReview();renderCanvas();await Promise.all([loadItems(),loadProjects()]);toast(submit?'已提交审核':'进度已保存')}catch(error){toast(error.message)}}
async function reviewItem(approve){if(!item)return;const comment=approve?'':prompt('填写驳回原因，标注员会看到：','请修正标注框')||'';if(!approve&&!comment)return;try{const result=await api('/api/item/review',{method:'POST',body:{item_id:item.id,approve,comment}});item=result.item;renderReview();await Promise.all([loadItems(),loadProjects()]);toast(approve?'审核通过':'已驳回修改')}catch(error){toast(error.message)}}
function itemIndex(){return items.findIndex(x=>x.id===item?.id)}function previousItem(){const index=itemIndex();if(items.length)openItem(items[Math.max(0,index-1)].id)}function nextItem(){const index=itemIndex();if(items.length)openItem(items[Math.min(items.length-1,index<0?0:index+1)].id)}
async function createProject(){try{const labels=document.getElementById('newProjectLabels').value.split(/[,;，；\n]+/).map(x=>x.trim()).filter(Boolean);const result=await api('/api/projects',{method:'POST',body:{name:document.getElementById('newProjectName').value,labels,source_dir:document.getElementById('newProjectSource').value}});await loadProjects();await selectProject(result.project.id);toast(`项目已创建，导入 ${result.project.imported} 张图片`)}catch(error){toast(error.message)}}
async function createUser(){try{await api('/api/users',{method:'POST',body:{username:document.getElementById('newUsername').value,password:document.getElementById('newPassword').value,role:document.getElementById('newRole').value}});await loadUsers();toast('成员账号已创建')}catch(error){toast(error.message)}}
async function assignTasks(){if(!project)return toast('请先选择项目');try{const result=await api('/api/tasks/assign',{method:'POST',body:{project_id:project.id,assignee_id:Number(document.getElementById('assignUser').value),count:Number(document.getElementById('assignCount').value)}});await Promise.all([loadItems(),loadProjects()]);toast(`已分配 ${result.assigned} 张图片`)}catch(error){toast(error.message)}}
function downloadExport(format){if(!project)return toast('请先选择项目');window.location.href=`/api/export?project_id=${project.id}&format=${encodeURIComponent(format)}`}
async function importPackage(){try{const result=await api('/api/project-package/import',{method:'POST',body:{path:document.getElementById('packagePath').value}});await loadProjects();await selectProject(result.project.id);toast(`项目包已导入 ${result.project.imported} 张图片`)}catch(error){toast(error.message)}}
function toggleAdmin(force){const drawer=document.getElementById('adminDrawer');drawer.classList.toggle('hidden',force===undefined?!drawer.classList.contains('hidden'):!force)}function toggleRight(){document.getElementById('rightPanel').classList.toggle('mobile-hidden')}
window.addEventListener('beforeunload',()=>{if(item)navigator.sendBeacon('/api/item/release',new Blob([JSON.stringify({item_id:item.id})],{type:'application/json'}))});window.addEventListener('resize',()=>renderCanvas());bootstrap().catch(error=>toast(error.message));
</script>
</body>
</html>'''
